#!/bin/sh
# SPDX-FileCopyrightText: 2026 amivuln contributors
# SPDX-License-Identifier: MIT OR Apache-2.0
#
# Differential check of the Debian comparator against the real dpkg, run in a
# debian:stable container with the difftool binary mounted at /tool:
#   podman run --rm -v ./deb.pairs:/pairs:ro -v ./tests/integration/debian-vs-dpkg.sh:/t.sh:ro \
#     docker.io/library/debian:stable sh -c "sh /t.sh"
# The pairs file is generated by a scratch binary that serializes
# amivuln_version::DebVersion comparisons over a generated corpus (see the
# amivuln-version tests for the corpus generator).
set -u
bad=0; n=0; skipped=0
while read -r a b want; do
  if ! dpkg --compare-versions "$a" lt "$b" >/dev/null 2>&1 && ! dpkg --compare-versions "$a" gt "$b" >/dev/null 2>&1 && ! dpkg --compare-versions "$a" eq "$b" >/dev/null 2>&1; then
    skipped=$((skipped + 1)); continue
  fi
  n=$((n + 1))
  if dpkg --compare-versions "$a" lt "$b" 2>/dev/null; then got=-1
  elif dpkg --compare-versions "$a" gt "$b" 2>/dev/null; then got=1
  else got=0
  fi
  if [ "$got" != "$want" ]; then
    bad=$((bad + 1))
    [ $bad -lt 12 ] && echo "MISMATCH $a $b ours=$want dpkg=$got"
  fi
done < /pairs
echo "$n pairs compared, $skipped skipped by dpkg as invalid, $bad mismatches"
[ "$bad" -eq 0 ]
